1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	} from './orchestratorHelpers.js';
25	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
26	import {log} from '../shared/logger.js';
27	
28	const DEFAULT_MAX_TOOL_ROUNDS = 5;
29	
30	export interface OrchestratorHooks {
31	  beforeSession?: (session: ChatSession) => Promise<void>;
32	  afterSession?: (session: ChatSession) => Promise<void>;
33	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
34	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
35	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
36	  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: UsageMetadata) => Promise<void>;
37	  onError?: (session: ChatSession, error: Error) => Promise<void>;
38	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
39	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
40	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
41	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
42	}
43	
44	export interface ToolBudgetInfo {
45	  maxToolRounds: number;
46	  requestedTools: string[];
47	}
48	
49	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
50	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
51	
52	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
53	
54	export interface ChatOrchestrator {
55	  processMessage(session: ChatSession): Promise<string>;
56	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
57	}
58	
59	export interface ChatOrchestratorOptions {
60	  maxToolRounds?: number;
61	  contextConfig?: Partial<ContextConfig>;
62	  promptBuilderOptions?: PromptBuilderOptions;
63	  hooks?: OrchestratorHooks;
64	  sessionStore?: SessionStore;
65	}
66	
67	interface ToolExecutionResult {
68	  clientMessages: OutgoingMessage[];
69	  suppressOutput: boolean;
70	}
71	export function createChatOrchestrator(
72	  provider: AIProvider,
73	  promptBuilder: PromptBuilder,
74	  toolRegistry?: ToolRegistry,
75	  options?: ChatOrchestratorOptions
76	): ChatOrchestrator {
77	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
78	  const contextConfig = createContextConfig(options?.contextConfig);
79	  const toolInstructions = toolRegistry?.getPromptInstructions();
80	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
81	  const tools = toolRegistry?.getDefinitions();
82	  const hooks = options?.hooks;
83	  const sessionStore = options?.sessionStore;
84	
85	  return {
86	    async processMessage(session: ChatSession): Promise<string> {
87	      return collectText(this.processMessageStream(session));
88	    },
89	
90	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
91	      try {
92	        if (hooks?.beforeSession) await hooks.beforeSession(session);
93	
94	        let userMessage = lastUserContent(session);
95	
96	        if (hooks?.beforeUserInput) {
97	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
98	        }
99	
100	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
101	
102	        const systemPrompt = hooks?.beforeModelResponse
103	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
104	          : baseSystemPrompt;
105	
106	        const messages: Message[] = toMessages(session.entries, contextConfig);
107	        let totalUsage: UsageMetadata | undefined;
108	        let responseText = '';
109	
110	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
111	        for (let round = 0; ; round++) {
112	          log.info('orchestrator', 'starting round', {round});
113	          const pendingToolCalls: ToolCall[] = [];
114	
115	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
116	          responseText += outcome.text;
117	          totalUsage = accumulateUsage(totalUsage, outcome.usage);
118	
119	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
120	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
121	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
122	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
123	            break;
124	          }
125	
126	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
127	          const {clientMessages, suppressOutput} = await executeToolCalls(
128	            pendingToolCalls,
129	            messages,
130	            session,
131	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
132	          );
133	          log.info('orchestrator', 'tool execution complete', {
134	            clientMessageCount: clientMessages.length,
135	            clientMessageTypes: clientMessages.map(m => m.type),
136	            suppressOutput,
137	          });
138	
139	          if (clientMessages.length > 0) {
140	            yield {type: 'tool_result' as const, clientMessages};
141	          }
142	
143	          if (suppressOutput) {
144	            yield {type: 'suppress_output' as const};
145	          }
146	        }
147	
148	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
149	      } catch (error) {
150	        if (hooks?.onError) {
151	          const wrapped = error instanceof Error ? error : new Error(String(error), {cause: error});
152	          await hooks.onError(session, wrapped);
153	        }
154	        throw error;
155	      } finally {
156	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
157	        commitStreamingEntries(session);
158	        try {
159	          if (hooks?.afterSession) await hooks.afterSession(session);
160	        } finally {
161	          await saveSession(sessionStore, session);
162	        }
163	      }
164	    },
165	  };
166	}
167	
168	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
169	function normalizeToolRounds(value: number | undefined): number {
170	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
171	  return Math.max(0, Math.floor(value));
172	}
173	
174	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
175	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
176	  if (round < maxToolRounds) return false;
177	  log.warn('orchestrator', 'tool budget exhausted', {
178	    maxToolRounds,
179	    requestedTools: pendingToolCalls.map(tc => tc.name),
180	  });
181	  return true;
182	}
183	
184	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
185	async function* closeExhaustedTurn(
186	  session: ChatSession,
187	  budget: ToolBudgetInfo,
188	  hook?: OnToolBudgetExhausted
189	): AsyncGenerator<MessageChunk, string> {
190	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
191	  if (sentence !== '') yield {type: 'text', text: sentence};
192	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
193	  return sentence;
194	}
195	
196	interface RoundOutcome {
197	  stopReason: string;
198	  text: string;
199	  usage?: UsageMetadata;
200	}
201	
202	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
203	async function* streamRound(
204	  provider: AIProvider,
205	  request: SendMessageParams,
206	  pendingToolCalls: ToolCall[]
207	): AsyncGenerator<MessageChunk, RoundOutcome> {
208	  let stopReason = '';
209	  let text = '';
210	  let usage: UsageMetadata | undefined;
211	
212	  for await (const chunk of provider.sendMessage(request)) {
213	    yield chunk;
214	    collectToolCalls(chunk, pendingToolCalls);
215	    stopReason = extractStopReason(chunk) ?? stopReason;
216	    usage = extractUsage(chunk) ?? usage;
217	    if (chunk.type === 'text') text += chunk.text;
218	  }
219	
220	  return {stopReason, text, usage};
221	}
222	
223	// A changed message is also written back to the session's last user entry.
224	async function rewriteUserMessage(
225	  session: ChatSession,
226	  userMessage: string,
227	  hook: (session: ChatSession, userMessage: string) => Promise<string>
228	): Promise<string> {
229	  const modified = await hook(session, userMessage);
230	  if (modified === userMessage) return userMessage;
231	
232	  updateLastUserContent(session, modified);
233	  return modified;
234	}
235	
236	function lastUserContent(session: ChatSession): string {
237	  for (let i = session.entries.length - 1; i >= 0; i--) {
238	    const entry = session.entries[i];
239	    if (entry.role === 'user') return entry.content;
240	  }
241	  return '';
242	}
243	
244	function updateLastUserContent(session: ChatSession, content: string): void {
245	  for (let i = session.entries.length - 1; i >= 0; i--) {
246	    const entry = session.entries[i];
247	    if (entry.role === 'user') {
248	      entry.content = content;
249	      return;
250	    }
251	  }
252	}
253	
254	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
255	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
256	  const context: ToolContext = {
257	    userId: session.userId,
258	    sessionId: session.sessionId,
259	    workspaceId: session.workspaceId,
260	    authHeaders: session.authHeaders,
261	  };
262	
263	  return async (tc: ToolCall): Promise<ToolResponse> => {
264	    const declined =
265	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
266	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
267	  };
268	}
269	
270	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
271	async function consultPolicy(
272	  policy: BeforeToolCall,
273	  session: ChatSession,
274	  tc: ToolCall
275	): Promise<ToolResponse | undefined> {
276	  try {
277	    return await policy(session, tc);
278	  } catch (error) {
279	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
280	      tool: tc.name,
281	      errorType: error instanceof Error ? error.name : typeof error,
282	    });
283	    return {result: `The ${tc.name} call was declined and not performed.`};
284	  }
285	}
286	
287	async function executeToolCalls(
288	  pendingToolCalls: ToolCall[],
289	  messages: Message[],
290	  session: ChatSession,
291	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
292	): Promise<ToolExecutionResult> {
293	  messages.push(buildToolCallMessages(pendingToolCalls));
294	
295	  const responses = await Promise.all(
296	    pendingToolCalls.map(async tc => {
297	      const response = await runToolCall(tc);
298	      return {tc, response};
299	    })
300	  );
301	
302	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
303	    type: 'tool_result' as const,
304	    toolUseId: tc.id,
305	    content: response.result,
306	  }));
307	  messages.push({role: 'user', content: toolResults});
308	
309	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
310	
311	  return {
312	    clientMessages: assignEntryIndices(rawClientMessages, session),
313	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
314	  };
315	}
316	
317	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
318	  return clientMessages.map(msg => {
319	    if (msg.type !== 'entry_upsert') return msg;
320	    const index = appendEntry(session, msg.entry);
321	    return {...msg, index};
322	  });
323	}
324	
325	// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
326	function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
327	  if (!acc) return next;
328	  if (!next) return acc;
329	  return {
330	    inputTokens: acc.inputTokens + next.inputTokens,
331	    outputTokens: acc.outputTokens + next.outputTokens,
332	    totalTokens: acc.totalTokens + next.totalTokens,
333	  };
334	}
335	
336	// A store outage is not a reason to fail the turn the customer already received.
337	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
338	  if (!store?.save) return;
339	
340	  try {
341	    await store.save(session);
342	  } catch (error) {
343	    const message = error instanceof Error ? error.message : String(error);
344	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
345	  }
346	}
